CREATE TABLE host_pairing_codes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),code_hash text NOT NULL,expires_at timestamptz NOT NULL,attempts integer NOT NULL DEFAULT 0,consumed_at timestamptz);
CREATE TABLE host_nodes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),name text NOT NULL,public_key text NOT NULL,token_hash text NOT NULL,capabilities jsonb NOT NULL DEFAULT '[]',grants jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,revoked_at timestamptz,last_seen_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,public_key));
ALTER TABLE schedules ADD FOREIGN KEY(host_id) REFERENCES host_nodes(id) DEFERRABLE;
CREATE TABLE host_identity_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),host_id uuid NOT NULL REFERENCES host_nodes(id) DEFERRABLE,actor_id uuid NOT NULL REFERENCES world_characters(id) DEFERRABLE,remote_identity text NOT NULL,enabled boolean NOT NULL DEFAULT true,revision integer NOT NULL DEFAULT 1,UNIQUE(host_id,actor_id));
CREATE TABLE host_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),host_id uuid NOT NULL REFERENCES host_nodes(id) DEFERRABLE,link_id uuid NOT NULL REFERENCES host_identity_links(id) DEFERRABLE,operation_id uuid NOT NULL,kind text NOT NULL,scope jsonb NOT NULL,payload jsonb NOT NULL,payload_hash text NOT NULL,budget jsonb NOT NULL,state text NOT NULL DEFAULT 'pending',execution_id uuid,epoch integer,schedule_id uuid REFERENCES schedules(id) DEFERRABLE,accepted_at timestamptz,result jsonb,error_code text,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,operation_id));
ALTER TABLE schedule_occurrences ADD FOREIGN KEY(host_job_id) REFERENCES host_jobs(id) DEFERRABLE;
CREATE TABLE host_receipts(job_id uuid NOT NULL REFERENCES host_jobs(id) DEFERRABLE,receipt_id uuid NOT NULL,payload_hash text NOT NULL,body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(job_id,receipt_id));
CREATE TABLE host_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),link_id uuid NOT NULL REFERENCES host_identity_links(id) DEFERRABLE,revision integer NOT NULL DEFAULT 1,materials jsonb NOT NULL,source_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
